'use client';

import { useCallback, useRef, useSyncExternalStore } from "react";

// src/_useSelector.ts
/**
* Subscribes to a store and returns the selected value, re-rendering when it
* changes (by `Object.is`). The selector runs again only when the store's
* state or the selector itself changes.
*/
function useSelector(store, selector) {
	const subscribe = useCallback((onChange) => store.subscribe(onChange).unsubscribe, [store]);
	const memoRef = useRef(null);
	const getSelection = () => {
		const state = store.get();
		const last = memoRef.current;
		if (last && last.selector === selector && Object.is(last.state, state)) return last.selected;
		memoRef.current = {
			state,
			selector,
			selected: selector(state)
		};
		return memoRef.current.selected;
	};
	return useSyncExternalStore(subscribe, getSelection, getSelection);
}

export { useSelector };